create or replace function public.revise_trade_chain(target_chain_id uuid,expected_version integer,payload jsonb)returns void language plpgsql security definer set search_path=public as $$declare c public.trade_chains;item jsonb;participant uuid;begin select * into c from public.trade_chains where id=target_chain_id for update;if not public.is_chain_participant(c.id)or c.version<>expected_version or c.status not in('proposed','accepted','active')then raise exception 'current editable chain required';end if;if c.status='active'and exists(select 1 from public.trade_chain_links where chain_id=c.id and fulfilled_at is not null)then raise exception 'fulfilled active chains require cancellation or dispute';end if;for participant in select distinct(value->>'from_profile_id')::uuid from jsonb_array_elements(payload->'links')loop if not exists(select 1 from public.circle_members where circle_id=c.circle_id and profile_id=participant and status='active')then raise exception 'replacement participants must be active in the circle';end if;end loop;delete from public.trade_chain_links where chain_id=c.id;for item in select value from jsonb_array_elements(payload->'links')loop insert into public.trade_chain_links(chain_id,from_profile_id,to_profile_id,value_description,position,due_at,conditions)values(c.id,(item->>'from_profile_id')::uuid,(item->>'to_profile_id')::uuid,trim(item->>'value_description'),coalesce((item->>'position')::int,0),nullif(item->>'due_at','')::timestamptz,coalesce(item->>'conditions',''));end loop;perform public.validate_trade_chain(c.id);update public.trade_chains set title=coalesce(payload->>'title',title),description=coalesce(payload->>'description',description),execution_mode=coalesce(payload->>'execution_mode',execution_mode),version=version+1,status='proposed',updated_at=now()where id=c.id;delete from public.trade_chain_acceptances where chain_id=c.id;insert into public.trade_chain_history(chain_id,actor_id,event,note,snapshot)values(c.id,auth.uid(),'renegotiated','Participants or terms changed; all confirmations reset',payload);for participant in select distinct from_profile_id from public.trade_chain_links where chain_id=c.id loop if participant<>auth.uid()then perform public.notify_user(participant,'network','Trade chain needs renewed consent',c.title||' was renegotiated. Review the complete new version.');end if;end loop;end$$;
